    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=[
        'add', 'subtract', 'multiply', 'divide', 'power', 'modulo', 'sqrt', 
        'memory_store', 'memory_recall', 'memory_clear', 'evaluate', 'get_history', 'clear_history'
    ], required=True)

    # Arguments used across different operations
    parser.add_argument("--a", type=float, help="First operand")
    parser.add_argument("--b", type=float, help="Second operand")
    parser.add_argument("--key", type=str, help="Memory key")
    parser.add_argument("--val", type=float, help="Memory value")
    parser.add_argument("--expr", type=str, help="Math expression for evaluation")

