    calc = Calculator()

    try:
        if args.op in ['add', 'subtract', 'multiply', 'divide', 'power', 'modulo']:
            result = getattr(calc, args.op)(args.a, args.b)
        elif args.op == 'sqrt':
            result = calc.sqrt(args.a)
        elif args.op == 'evaluate':
            result = calc.evaluate(args.expr)
        elif args.op == 'memory_store':
            if args.key:
                calc.memory_store(args.key, args.val)
            else:
                calc.memory_store(args.val)
            print("Value stored.")
